1	"use client";
2	
3	/**
4	 * Client form bound to `loginSchema` and the login action.
5	 *
6	 * Owner D. The same Zod schema runs twice: here, to render field errors without
7	 * a round trip, and again inside `loginAction` on the server — the client copy
8	 * is a convenience, never the enforcement.
9	 *
10	 * Must call (do not reimplement): loginSchema
11	 */
12	
13	import { useActionState, useEffect } from "react";
14	import { useRouter } from "next/navigation";
15	import Link from "next/link";
16	import { loginAction } from "@/actions/auth/login";
17	import { fieldErrorsFromZod } from "@/lib/errors";
18	import { loginSchema } from "@/schemas/auth";
19	import type { ActionResult } from "@/types/api";
20	import type { SessionPrincipal } from "@/types/member";
21	
22	export type LoginFormProps = {
23	  /** Where to land after a successful sign-in; defaults to the org chooser. */
24	  next: string;
25	};
26	
27	type LoginState = ActionResult<SessionPrincipal> | null;
28	
29	export function LoginForm(props: LoginFormProps) {
30	  const router = useRouter();
31	
32	  const [state, submit, pending] = useActionState<LoginState, FormData>(
33	    async (_previous, formData) => {
34	      const parsed = loginSchema.safeParse({
35	        email: String(formData.get("email") ?? ""),
36	        password: String(formData.get("password") ?? ""),
37	        rememberMe: formData.get("rememberMe") === "on",
38	      });
39	
40	      if (!parsed.success) {
41	        return {
42	          ok: false,
43	          error: {
44	            code: "validation_failed",
45	            message: "Check the fields below.",
46	            fieldErrors: fieldErrorsFromZod(parsed.error),
47	          },
48	        };
49	      }
50	
51	      return loginAction(parsed.data);
52	    },
53	    null,
54	  );
55	
56	  useEffect(() => {
57	    if (state?.ok === true) {
58	      router.push(props.next);
59	    }
60	  }, [state, router, props.next]);
61	
62	  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};
63	
64	  return (
65	    <form action={submit} className="space-y-5">
66	      <h1 className="text-lg font-semibold">Sign in</h1>
67	
68	      {state?.ok === false && state.error.code !== "validation_failed" ? (
69	        <p role="alert" className="rounded bg-rose-50 px-3 py-2 text-sm text-rose-700">
70	          {state.error.message}
71	        </p>
72	      ) : null}
73	
74	      <div className="space-y-1">
75	        <label htmlFor="email" className="text-sm font-medium">
76	          Email
