const SESSION_TTL_DAYS_REMEMBERED = 30;
const SESSION_TTL_HOURS_DEFAULT = 24;
const MS_PER_DAY = 24 * 60 * 60 * 1000;
const MS_PER_HOUR = 60 * 60 * 1000;

/** Length in bytes of the raw session token handed to the browser. */
const TOKEN_BYTES = 32;

/**
 * Mints a session. Only the hash reaches the database, so a dump of the
 * `sessions` table cannot be replayed as a login. `rememberMe` is the only
 * thing that changes the lifetime: 24 hours by default, 30 days when set —
 * a shared computer left on the login page should not stay signed in for a
 * month just because nobody unchecked the box.
 */
export async function createSessionToken(
